function getGruposLibres(year) {
    if (!_cache[year] && year === 2027) {
        _cache[year] = _EXACT_2027;
    }
    if (!_cache[year]) {
        _cache[year] = {
            t7327: _calcGrupos(year, _P7327),
            t8020: _calcGrupos(year, _P8020),
            // Todos los años se calculan (el cálculo coincide con los PDF oficiales de 2026)
            t7327mt: _calcGrupos(year, _P7327MT),
            t8020mt: _calcGrupos(year, _P8020MT)
        };
    }
    return _cache[year];
}

function getDiasLibres(year, grupo, turno) {
    const g = getGruposLibres(year);
    if (turno === '80/20') return g.t8020[grupo] || {};
    if (turno === '73/27 MT' || turno === '73/27MT') return g.t7327mt[grupo] || {};
    if (turno === '80/20 MT' || turno === '80/20MT') return g.t8020mt[grupo] || {};
    return g.t7327[grupo] || {}; // 73/27 noche por defecto
}

